"""Reproduce ten illustrated READMEs and self-contained offline HTML guides."""
import argparse
import json
import posixpath
import re
from html import escape
from pathlib import Path
import shutil
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
RELEASE = 'https://github.com/vhaloo/MarioCompilationUltra/releases/tag/v0.4.0'
ABOUT = 'A local SNES collection with an adaptive PC interface and experimental world views. Snes9x supplies the cartridge simulation, including Super FX. No decompilation of every game is claimed.'
LEGAL = 'Use cartridges you are entitled to use. This independent, noncommercial project is not affiliated with Nintendo. Names identify compatible games. No ROM, artwork, music, extracted level pack or game screenshot is distributed.'
LICENSES = 'Original code: MIT · Snes9x: noncommercial licence · SDL2/zlib: zlib · Dear ImGui: MIT · font: SIL OFL. The bundled licences and corresponding sources accompany the release.'
CONTROLS = next(key for key in json.loads((ROOT / 'assets/locales/en.json').read_text(encoding='utf8')) if key.startswith('KEYBOARD\n'))
PAGES = ['Collection', 'Screen', 'Camera & scenery', 'Saves & sound', 'Controls', 'About', 'questtab']
EDITIONS = [('f84305b1','All-Stars + World (US)'),('925637c7','All-Stars (US)'),('b19ed489','Super Mario World (US)'),('d138f224','Yoshi’s Island 1.0 (US)'),('cf98ddaa','Yoshi’s Island 1.1 (US)')]
def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--captures', type=Path)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    languages = json.loads((ROOT / 'assets/locales/languages.json').read_text(encoding='utf8'))
    paragraphs = json.loads((ROOT / 'docs/guide-texts.json').read_text(encoding='utf8'))
    assert all(len(values) == len(languages) and all(values) for values in paragraphs.values())
    outputs = {}
    for index, language in enumerate(languages):
        code = language['code']
        directory = ROOT / 'docs' / code
        directory.mkdir(parents=True, exist_ok=True)
        catalog = json.loads((ROOT / f'assets/locales/{code}.json').read_text(encoding='utf8'))
        tr = lambda key: catalog[key]
        para = lambda key: paragraphs[key][index]
        nav = ' · '.join(f"[{item['name']}](../{item['code']}/README.md)" for item in languages)
        md = f'<!-- Generated by tools/guides.py; edit docs/guide-texts.json and assets/locales. -->\n![Mario Compilation Ultra](hero.svg)\n\n{nav}\n\n# Mario Compilation Ultra 0.4.0\n\n{tr(ABOUT)}\n\n[{para("download_heading")}]({RELEASE}) · [HTML](guide.html) · [GitHub](https://github.com/vhaloo/MarioCompilationUltra)\n\n'
        md += f'## {para("download_heading")}\n\n' + '\n'.join(f'{number}. {para(key)}' for number, key in enumerate(['setup1','setup2','setup3'],1)) + '\n\n' + para('shortcut') + '\n\n'
        md += '```powershell\n# Windows\npowershell -NoProfile -ExecutionPolicy Bypass -File .\\Install-Windows.ps1\n```\n\n```sh\n# Linux\nsh ./Install-Linux.sh\n```\n\n'
        md += f'![{tr("Collection")}](screenshots/0.png)\n\n*{para("gallery_note")}*\n\n'
        md += f'## {para("platform_heading")}\n\n- {para("windows_status")}\n- {para("linux_status")}\n- **{para("mac_status")}**\n\n'
        md += f'## {tr("View modes")}\n\n![{tr("View modes")}](views.svg)\n\n{para("display_defaults")}\n\n{para("view_details")}\n\n{para("editions")}\n\n'
        md += '| CRC32 | SNES |\n|---|---|\n' + ''.join(f'| `{crc}` | {name} |\n' for crc,name in EDITIONS) + '\n'
        md += f'## {tr("questtab")}\n\n[Quest ARM64 APK](https://github.com/vhaloo/MarioCompilationUltra/releases/download/v0.4.0/MarioCompilationUltra-0.4.0-Quest-public.apk) · [{tr("questtab")}](XR.md) · [HTML](xr.html) · [Parity](../PARITY.md)\n\n'
        md += f'## {tr("Controls")}\n\n' + tr(CONTROLS).replace('\n', '<br>\n') + '\n\n'
        md += f'## {tr("Saves & sound")}\n\n{para("save_details")}\n\n## {tr("Local files")}\n\n{para("data_note")}\n\n'
        md += '| OS | '+tr('Local cartridge folder')+' |\n|---|---|\n| Windows | `%APPDATA%/ValentinWittwe/MarioCompilationUltra/` |\n| Linux | `$XDG_DATA_HOME/ValentinWittwe/MarioCompilationUltra/` or `~/.local/share/ValentinWittwe/MarioCompilationUltra/` |\n| macOS | `~/Library/Application Support/ValentinWittwe/MarioCompilationUltra/` |\n\n'
        md += para('data_override') + '\n\n'
        md += f'## {para("troubleshooting_heading")}\n\n{para("troubleshooting")}\n\n## {para("gallery_heading")}\n\n'
        md += ''.join(f'### {tr(page)}\n\n![{tr(page)}](screenshots/{page_index}.png)\n\n' for page_index,page in enumerate(PAGES))
        md += f'## {para("platform_heading")} · 0.4.0\n\n{para("validation_note")}\n\n[CTest / CI](https://github.com/vhaloo/MarioCompilationUltra/actions) · [Report](../TEST_REPORT.md) · [Build](../BUILD.md) · [Source / research](../RESEARCH.md)\n\n{tr(LEGAL)}\n\n{tr(LICENSES)}\n\n[Licence](../../LICENSE) · [Third-party notices](../../THIRD_PARTY_NOTICES.md)\n'
        outputs[directory / 'README.md'] = md
        language_nav = ''.join(f'<a href="../{item["code"]}/guide.html" lang="{item["code"]}">{escape(item["name"])}</a>' for item in languages)
        h = lambda text: escape(text)
        section = lambda title, body: f'<section><h2>{h(title)}</h2>{body}</section>'
        body = f'<header><img src="hero.svg" alt="Mario Compilation Ultra"><nav aria-label="Languages">{language_nav}</nav><h1>Mario Compilation Ultra <span>0.4.0</span></h1><p>{h(tr(ABOUT))}</p><a class="download" href="{RELEASE}">{h(para("download_heading"))}</a></header>'
        body += section(para('download_heading'), '<ol>' + ''.join(f'<li>{h(para(key))}</li>' for key in ['setup1','setup2','setup3']) + f'</ol><p>{h(para("shortcut"))}</p><pre>Windows: powershell -NoProfile -ExecutionPolicy Bypass -File .\\Install-Windows.ps1\nLinux: sh ./Install-Linux.sh</pre><img src="screenshots/0.png" alt="{h(tr("Collection"))}">')
        body += section(para('platform_heading'), '<ul>' + ''.join(f'<li>{h(para(key))}</li>' for key in ['windows_status','linux_status','mac_status']) + '</ul>')
        body += section(tr('View modes'), f'<img src="views.svg" alt="{h(tr("View modes"))}"><p>{h(para("display_defaults"))}</p><p>{h(para("view_details"))}</p><p>{h(para("editions"))}</p><table><thead><tr><th>CRC32</th><th>SNES</th></tr></thead><tbody>' + ''.join(f'<tr><td><code>{crc}</code></td><td>{h(name)}</td></tr>' for crc,name in EDITIONS) + '</tbody></table>')
        body += section(tr('questtab'), f'<p><a href="xr.html">{h(tr("questtab"))}</a></p>')
        body += section(tr('Controls'), f'<pre class="controls">{h(tr(CONTROLS))}</pre>')
        body += section(tr('Saves & sound'), f'<p>{h(para("save_details"))}</p>')
        body += section(tr('Local files'), f'<p>{h(para("data_note"))}</p><pre>Windows: %APPDATA%/ValentinWittwe/MarioCompilationUltra/\nLinux: ~/.local/share/ValentinWittwe/MarioCompilationUltra/\nmacOS: ~/Library/Application Support/ValentinWittwe/MarioCompilationUltra/</pre><p>{h(para("data_override"))}</p>')
        body += section(para('troubleshooting_heading'), f'<p>{h(para("troubleshooting"))}</p>')
        body += section(para('gallery_heading'), f'<p>{h(para("gallery_note"))}</p><div class="gallery">' + ''.join(f'<figure><img loading="lazy" src="screenshots/{i}.png" alt="{h(tr(page))}"><figcaption>{h(tr(page))}</figcaption></figure>' for i,page in enumerate(PAGES)) + '</div>')
        body += section(para('platform_heading') + ' · 0.4.0', f'<p>{h(para("validation_note"))}</p><p><a href="https://github.com/vhaloo/MarioCompilationUltra/actions">CTest / CI</a> · <a href="../TEST_REPORT.md">Report</a> · <a href="../BUILD.md">Build</a></p>')
        body += f'<footer><p>{h(tr(LEGAL))}</p><p>{h(tr(LICENSES))}</p><a href="../../THIRD_PARTY_NOTICES.md">Third-party notices</a></footer>'
        css = '''@font-face{font-family:MCU;src:url(../../assets/Interface.otf)}*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#0c131c;color:#edf3f0;font:17px/1.65 MCU,system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:32px}h1,h2,h3{line-height:1.3}h1 span{color:#a0d1b6;font-size:.6em}h2{color:#a0d1b6;margin-top:0}a{color:#a9d7e2}nav{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}section{padding:32px;margin:28px 0;background:#14202d;border:1px solid #314353;border-radius:18px}img{display:block;width:100%;height:auto;border-radius:12px}li{margin:16px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;background:#0c1722;padding:20px;border-radius:10px}code{font-size:90%}.download{display:inline-block;background:#a0d1b6;color:#142332;padding:12px 22px;border-radius:10px;font-weight:700;text-decoration:none}table{border-collapse:collapse;width:100%}td,th{padding:12px;text-align:left;border-bottom:1px solid #395363}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}figure{margin:0}figcaption{color:#b4c9d0;padding:8px}footer{color:#b7c7d0;padding:24px 0}@media(max-width:650px){body{font-size:16px}main{padding:14px}section{padding:18px}.gallery{grid-template-columns:1fr}}'''
        outputs[directory / 'guide.html'] = f'<!doctype html>\n<html lang="{code}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mario Compilation Ultra · {h(language["name"])}</title><style>{css}</style></head><body><main>{body}</main></body></html>\n'
        if args.captures:
            gallery = directory / 'screenshots'
            gallery.mkdir(exist_ok=True)
            for page in range(7):
                with Image.open(args.captures / '1920x1080' / f'{code}-{page}.png') as capture:
                    assert capture.size == (1920, 1080)
                    # Crop only the unused surround; the real application pixels are unchanged.
                    capture.crop((338, 78, 1582, 1002)).save(gallery / f'{page}.png')
    for path, content in outputs.items():
        if args.check:
            assert path.read_text(encoding='utf8') == content, f'Regenerate {path.relative_to(ROOT)}'
        else:
            path.write_text(content, encoding='utf8', newline='\n')
    english = outputs[ROOT / 'docs/en/README.md']
    def root_link(match):
        target = match.group(1)
        if '://' not in target and not target.startswith('#'):
            target = posixpath.normpath('docs/en/' + target)
        return '](' + target + ')'
    english = re.sub(r'\]\(([^)]+)\)', root_link, english)
    packages = '| Windows x64 | Linux x64 | macOS Intel x64 | macOS Apple Silicon arm64 |\n|---|---|---|---|\n'
    packages += '| ' + ' | '.join(f'[ZIP{" — experimental" if "macos" in platform else ""}](https://github.com/vhaloo/MarioCompilationUltra/releases/download/v0.4.0/MarioCompilationUltra-0.4.0-{platform}.zip)' for platform in ['windows-x64','linux-x64','macos-x64','macos-arm64']) + ' |\n\nAll four packages contain all ten interface languages, illustrated guides, licences and original desktop icons.\n\n'
    english = english.replace('## Download and desktop startup\n\n', '## Download and desktop startup\n\n' + packages, 1)
    if args.check:
        assert (ROOT / 'README.md').read_text(encoding='utf8') == english, 'Regenerate the root README'
    else:
        (ROOT / 'README.md').write_text(english, encoding='utf8', newline='\n')
    print('Ten illustrated READMEs and offline HTML guides verified')
if __name__ == '__main__':
    main()
